const hre = require("hardhat");

async function main() {
  const HaitiAid = await hre.ethers.getContractFactory("HaitiAidShield");
  const contract = await HaitiAid.deploy();
  console.log("Success! HaitiAidShield deployed to:", contract.address);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});